{"command":"python3 << 'EOF'
import re

with open('reports/pipeline_report.md', 'r') as f:
    content = f.read()

# Find sections
sections = []
pattern = r'^#\s+(.+)$'
for match in re.finditer(pattern, content, re.MULTILINE):
    section_title = match.group(1).strip()
    # Get the text after this heading until the next heading
    start = match.end()
    rest = content[start:]
    next_match = re.search(pattern, rest)
    if next_match:
        end = next_match.start() + start
    else:
        end = len(content)
    section_text = rest[:end].strip()
    sections.append((section_title, len(section_text), section_text))

for title, length, text in sections:
    print(f"{title}: {length} chars")
    if length < 80:
        print(f"  WARNING: Less than 80 characters!")
    else:
        print(f"  OK: At least 80 characters")
EOF"}
